count = int(input())
shipments = {}
for _ in range(count):
    shipment_id, state = input().split("|", 1)
    shipments[shipment_id] = state

transitions = {
    ("created", "pack"): "packed",
    ("packed", "ship"): "shipped",
    ("shipped", "deliver"): "delivered",
}
invalid = 0
event_count = int(input())
for _ in range(event_count):
    shipment_id, action = input().split("|", 1)
    if shipment_id not in shipments:
        invalid += 1
        continue
    next_state = transitions.get((shipments[shipment_id], action))
    if next_state is None:
        invalid += 1
    else:
        shipments[shipment_id] = next_state

summary = ",".join(
    f"{shipment_id}:{shipments[shipment_id]}" for shipment_id in sorted(shipments)
)
print(f"{summary}|invalid={invalid}")

