use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut shipments = BTreeMap::new();

    for _ in 0..n {
        let (id, state) = lines.next().unwrap().split_once('|').unwrap();
        shipments.insert(id.to_string(), state.to_string());
    }

    let m: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut invalid = 0;
    for _ in 0..m {
        let (id, action) = lines.next().unwrap().split_once('|').unwrap();
        if let Some(state) = shipments.get_mut(id) {
            let next = match (state.as_str(), action) {
                ("created", "pack") => Some("packed"),
                ("packed", "ship") => Some("shipped"),
                ("shipped", "deliver") => Some("delivered"),
                _ => None,
            };
            if let Some(next_state) = next {
                *state = next_state.to_string();
            } else {
                invalid += 1;
            }
        } else {
            invalid += 1;
        }
    }

    let states = shipments
        .iter()
        .map(|(id, state)| format!("{id}:{state}"))
        .collect::<Vec<_>>()
        .join(",");
    println!("{states}|invalid={invalid}");
}

use std::fs;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let title = lines.next().unwrap_or("");
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    let notes: Vec<&str> = (0..n).map(|_| lines.next().unwrap_or("")).collect();
    let mut contents = String::new();
    contents.push_str(title);
    contents.push('\n');
    for note in notes {
        contents.push_str(note);
        contents.push('\n');
    }
    fs::write("file_backed_notes.txt", contents).unwrap();
    let saved = fs::read_to_string("file_backed_notes.txt").unwrap();
    let mut saved_lines = saved.lines();
    let saved_title = saved_lines.next().unwrap_or("");
    let saved_notes: Vec<&str> = saved_lines.take(n).collect();
    let nonempty = saved_notes.iter().filter(|note| !note.is_empty()).count();
    let characters: usize = saved_notes.iter().map(|note| note.len()).sum();
    println!("{}|{}|{}|{}", saved_title, n, nonempty, characters);
}
